        getChartData(state) {
            var labels = state.domainState.trustHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                trustChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.trustHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastRecord = history[history.length - 1];
            var finalTrust = lastRecord.results ? lastRecord.results.trustTotal : 50;
            var totalTrustChange = history.reduce(function(s, r) { return s + (r.results ? r.results.trustChange : 0); }, 0);

            var performance = this._t('perf_needs_improvement');
            if (finalTrust >= 80) performance = this._t('perf_excellent');
            else if (finalTrust >= 65) performance = this._t('perf_good');
            else if (finalTrust >= 50) performance = this._t('perf_fair');
            else if (finalTrust >= 35) performance = this._t('perf_poor');

            var insights = [];
            if (finalTrust >= 80) {
                insights.push(this._t('insight_excellent'));
            } else if (finalTrust >= 65) {
                insights.push(this._t('insight_good'));
            } else if (finalTrust >= 50) {
                insights.push(this._t('insight_fair'));
            } else {
                insights.push(this._t('insight_poor'));
            }

            return {
                finalTrust: finalTrust,
                totalTrustChange: totalTrustChange,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.trustTotal < 35) return window.mySimulation.t('hint_critical');
            if (results.trustChange < -10) return window.mySimulation.t('hint_major_loss');
            if (results.trustChange < 0) return window.mySimulation.t('hint_minor_loss');
            if (results.trustChange > 15) return window.mySimulation.t('hint_excellent');
            if (results.trustChange > 5) return window.mySimulation.t('hint_good');
            return null;
        }

